ty[]" maxlength="20" inputmode="decimal" value="<?= e($quantities[$i]??$item['quantity']) ?>" required></label></div><label class="admin-check"><input type="checkbox" name="exclude[]" value="<?= e($i) ?>" <?= in_array((string)$i,$values['exclude']??[],true)?'checked':'' ?>><span>No incluir este producto en el resultado</span></label></fieldset><?php endforeach?>
